def daily_returns(closes):
    rets = []
    for prev, cur in zip(closes, closes[1:]):
        rets.append((cur - prev) / prev)
    return rets

def to_line(trade):
    ticker, price, qty = trade
    return ",".join([ticker, f"{price:.2f}", str(qty)])

def parse_trade(line):
    ticker, price, qty = line.strip().split(",")
    return (ticker.strip().upper(), float(price), int(qty))
